const TRAILING_URL_PUNCTUATION = /[),.;:!?]+$/;


const PRIVATE_IPV4_PATTERNS: RegExp[] = [
  /^10\./,
  /^127\./,
  /^192\.168\./,
  /^169\.254\./,
  /^172\.(1[6-9]|2\d|3[0-1])\./,
  /^0\./,
  /^100\.(6[4-9]|[7-9]\d|1[01]\d|12[0-7])\./,
];

const PRIVATE_IPV6_PATTERNS: RegExp[] = [/^::1$/i, /^fe80:/i, /^f[cd][0-9a-f]{2}:/i];

const isIpv4MappedPrivateIpv6 = (address: string): boolean => {
  const match = /^::ffff:(\d+\.\d+\.\d+\.\d+)$/i.exec(address);
  if (!match) return false;
  return PRIVATE_IPV4_PATTERNS.some((pattern) => pattern.test(match[1]));
};

const LOCAL_HOSTNAME_PATTERNS: RegExp[] = [
  /^localhost$/i,
  /\.localhost$/i,
  /^localhost\./i,
  /\.local$/i,
  /\.internal$/i,
  /\.lan$/i,
  /\.intranet$/i,
];

export const isLocalLiteralHostname = (hostname: string): boolean => {
  const trimmed = hostname.replace(/^\[|\]$/g, '');
  if (PRIVATE_IPV4_PATTERNS.some((pattern) => pattern.test(trimmed))) return true;
  if (PRIVATE_IPV6_PATTERNS.some((pattern) => pattern.test(trimmed))) return true;
  if (isIpv4MappedPrivateIpv6(trimmed)) return true;
  if (LOCAL_HOSTNAME_PATTERNS.some((pattern) => pattern.test(trimmed))) return true;
  return false;
};

export const validateInspirationUrl = (
  rawUrl: string,
):
  | { ok: true; url: URL; normalized: string }
  | { ok: false; reason: string } => {
  const trimmed = rawUrl.trim();
  if (!trimmed) {
    return { ok: false, reason: 'URL is empty.' };
  }
  let parsed: URL;
  try {
    parsed = new URL(trimmed);
  } catch {
    return { ok: false, reason: `URL is not valid: ${trimmed}` };
  }
  if (parsed.protocol !== 'http:' && parsed.protocol !== 'https:') {
    return {
      ok: false,
      reason: `Only HTTP and HTTPS inspiration links are supported (got '${parsed.protocol.replace(/:$/, '')}').`,
    };
  }
  const hostname = parsed.hostname.toLowerCase();
  if (!hostname) {
    return { ok: false, reason: 'URL is missing a hostname.' };
  }
  if (isLocalLiteralHostname(hostname)) {
    return {
      ok: false,
      reason: `URL hostname '${hostname}' resolves to a local or private-network target.`,
    };
  }
  parsed.hash = '';
  return { ok: true, url: parsed, normalized: parsed.toString() };
};

export const normalizeUrl = (rawUrl: string): string | null => {
  const trimmed = rawUrl.trim().replace(TRAILING_URL_PUNCTUATION, '');
  if (!trimmed) return null;
  let parsed: URL;
  try {
    parsed = new URL(trimmed);
  } catch {
    return null;
  }
  if (parsed.protocol !== 'http:' && parsed.protocol !== 'https:') {
    return null;
  }
  const hostname = parsed.hostname.toLowerCase();
  if (!hostname || isLocalLiteralHostname(hostname)) {
    return null;
  }
  parsed.hash = '';
  return parsed.toString();
};
